    assert_eq!(candidate(vec!["abcdefghijklmnopqrstuvwxyz"], vec!["abcdefghijklmnopqrstuvwxyza","abcdefghijklmnopqrstuvwxyzb","abcdefghijklmnopqrstuvwxyzc","abcdefghijklmnopqrstuvwxyzd","abcdefghijklmnopqrstuvwxyze","abcdefghijklmnopqrstuvwxyzf","abcdefghijklmnopqrstuvwxy zg","abcdefghijklmnopqrstuvwxyzh","abcdefghijklmnopqrstuvwxyzi","abcdefghijklmnopqrstuvwxyzj","abcdefghijklmnopqrstuvwxyzk","abcdefghijklmnopqrstuvwxyzl","abcdefghijklmnopqrstuvwxyzm","abcdefghijklmnopqrstuvwxyzn","abcdefghijklmnopqrstuvwxyzo","abcdefghijklmnopqrstuvwxyzp","abcdefghijklmnopqrstuvwxyzq","abcdefghijklmnopqrstuvwxyza","abcdefghijklmnopqrstuvwxyzz"]), Error: negative shift count);
